function NavIcon({ icon, color }: { icon: keyof typeof ICON_PATHS; color: string }) {
  const { d, w, h } = ICON_PATHS[icon];
  return (
    <svg
      width={w}
      height={h}
      viewBox={`0 0 ${w} ${h}`}
      fill="none"
      className="shrink-0"
      style={{ minWidth: w }}
    >
      <path d={d} fill={color} />
    </svg>
  );
}

